        } elseif (!isset($sortedArguments['start']) && $parsedDate = $this->makeDateTime($argument)) {
            $sortedArguments['start'] = $parsedDate;
        } elseif (!isset($sortedArguments['end']) && ($parsedDate = $parsedDate ?? $this->makeDateTime($argument))) {
